-- The NBA (docs/prompts/nba.md, 2026-09-18): the third sport, keyed by sport_id like the other
-- two. This migration adds the sport, its reference rows (teams, aliases, colours, arenas,
-- shapes, home arenas, generated from seed/nba_teams.json and seed/nba_venues.json by
-- `python3 seed/scripts/build_seed_sql.py --only nba`), the sport-keyed rows of every table
-- that has them, the curated bucket lists with the venue noun per sport, live state for a
-- game clock, and the two scheduled calls (nba-sync every 15 minutes, nba-live every minute
-- while someone is checked in at an NBA game).
--
-- Local and hosted are already seeded, so the reference rows ride in the migration rather than
-- in seed.sql alone; seed.sql carries the same statements for a fresh database.

-- ---------------------------------------------------------------------------
-- 1. The sport
-- ---------------------------------------------------------------------------
alter table public.sports drop constraint if exists sports_id_check;
alter table public.sports add constraint sports_id_check check (id in ('mlb', 'nfl', 'nba'));
on conflict (id) do nothing;

