-- ---------------------------------------------------------------------------
-- 3. Live state: basketball has a game clock
-- ---------------------------------------------------------------------------
alter table public.game_live_state add column if not exists clock text;
comment on column public.game_live_state.clock is
  'Game clock remaining in the period as the scoreboard shows it ("2:31"). NBA only; null for MLB. The period is in inning and the state (live, end, halftime) in inning_state.';

-- Games that need live polling right now: any sport with a live feed, someone checked in,
-- within the live window. nba-live and mlb-live each take their own rows.
create or replace function public.games_needing_live_poll()
returns table (game_id uuid, provider_game_id text, sport_id text, scheduled_start timestamptz)
language sql
stable
security definer
set search_path = public
as $$
  select distinct g.id, g.provider_game_id, g.sport_id, g.scheduled_start
  from public.games g
  join public.checkins c on c.game_id = g.id
  where g.sport_id in ('mlb', 'nba')
    and g.status in ('scheduled', 'live')
    and now() between g.scheduled_start - interval '1 hour' and g.scheduled_start + interval '6 hours';
$$;

-- The estimate for the countdown (SPEC 6.4): the NBA locks at the end of the first quarter,
-- estimated at tip-off plus 30 minutes, the same figure as MLB.
create or replace function public.estimated_pledge_lock(p_sport text, p_start timestamptz)
returns timestamptz
language sql
immutable
as $$
  select case
    when p_sport = 'nfl' then p_start + interval '12 minutes'
    else p_start + interval '30 minutes'
  end;
$$;

-- ---------------------------------------------------------------------------
-- 4. Scheduled calls (proven through net._http_response, never cron.job_run_details)
-- ---------------------------------------------------------------------------
select cron.schedule('nba-sync', '*/15 * * * *', $$select public.call_edge_function('nba-sync')$$);
select cron.schedule('nba-live', '* * * * *',
  $$select public.call_edge_function('nba-live') where exists (select 1 from public.games_needing_live_poll() where sport_id = 'nba')$$);
-- mlb-live keeps its guard but should only fire for its own sport now that the function serves two.
select cron.unschedule('mlb-live');
select cron.schedule('mlb-live', '* * * * *',
  $$select public.call_edge_function('mlb-live') where exists (select 1 from public.games_needing_live_poll() where sport_id = 'mlb')$$);

-- Wrapped: the NBA season starts in October and ends in June, so eight months back names it.
select cron.unschedule('wrapped-daily');
select cron.schedule('wrapped-daily', '0 9 * * *', $$
  select public.publish_wrapped_if_season_over('mlb', extract(year from now())::integer);
  select public.publish_wrapped_if_season_over('nfl', extract(year from now() - interval '2 months')::integer);
  select public.publish_wrapped_if_season_over('nba', extract(year from now() - interval '8 months')::integer);
$$);

-- ---------------------------------------------------------------------------
-- 5. Sport-keyed rows in the famous games tables (20260918000100)
-- ---------------------------------------------------------------------------
on conflict (sport_id, honor) do nothing;

on conflict (sport_id, round) do nothing;

-- ---------------------------------------------------------------------------
-- 6. Curated bucket lists: the venue noun is the sport's (ballpark, stadium, arena)
-- ---------------------------------------------------------------------------
create or replace function public.venue_noun(p_sport text, p_plural boolean default false)
returns text
language sql
immutable
as $$
  select case p_sport
    when 'mlb' then case when p_plural then 'ballparks' else 'ballpark' end
    when 'nba' then case when p_plural then 'arenas' else 'arena' end
    else case when p_plural then 'stadiums' else 'stadium' end
  end;
$$;

create or replace function public.rebuild_curated_bucket_lists()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
begin
  -- All current venues of each league, in its own word.
  for r in
    select id as sport_id,
           case id
             when 'mlb' then 'All 30 MLB ballparks'
             when 'nba' then 'Every NBA arena'
             else 'Every NFL stadium'
           end as title
    from public.sports
  loop
    select r.sport_id || '-all-venues', r.title,
           'Every current home venue in the league.', true,
           jsonb_build_object('type', 'distinct_venues', 'target', count(distinct t.home_venue_id),
                              'filter', jsonb_build_object('venue_ids', jsonb_agg(distinct t.home_venue_id)))
    from public.teams t where t.sport_id = r.sport_id and t.active and t.home_venue_id is not null
    having count(distinct t.home_venue_id) > 0
    on conflict (slug) do update set title = excluded.title, definition = excluded.definition;
  end loop;

  -- Each division's venues.
  for r in select distinct sport_id, division from public.teams where active and division is not null and home_venue_id is not null loop
    select r.sport_id || '-division-' || lower(regexp_replace(r.division, '[^a-zA-Z0-9]+', '-', 'g')),
           r.division || ' ' || public.venue_noun(r.sport_id, true),
           'Every home venue in the ' || r.division || '.', true,
           jsonb_build_object('type', 'distinct_venues', 'target', count(distinct t.home_venue_id),
                              'filter', jsonb_build_object('venue_ids', jsonb_agg(distinct t.home_venue_id)))
    from public.teams t where t.sport_id = r.sport_id and t.division = r.division and t.active and t.home_venue_id is not null
    on conflict (slug) do update set title = excluded.title, definition = excluded.definition;
  end loop;

  -- Achievement lists.
  on conflict (slug) do update set title = excluded.title, description = excluded.description, definition = excluded.definition;
end;
$$;

select public.rebuild_curated_bucket_lists();
